export function testSelfRewardMechanism(environment, rewardFn) {
    const simulationResults = [];
    const maxCycles = Math.min(environment.simulationCycles || 100, 1000);

    for (let i = 0; i < maxCycles; i++) {
      const state = environment.getCurrentState();
      const reward = rewardFn(state);
      simulationResults.push({ cycle: i, state, reward });

      if (reward > environment.threshold) {
        environment.adjustStrategy(state, reward);
      }
    }

    return {
      totalCycles: simulationResults.length,
      avgReward: simulationResults.reduce((sum, r) => sum + r.reward, 0) / simulationResults.length,
      maxReward: Math.max(...simulationResults.map(r => r.reward)),
      converged: simulationResults.slice(-10).every(r => r.reward > environment.threshold * 0.9),
      results: simulationResults.slice(-20)
    };
  }